import { NextResponse } from 'next/server';
import { generateImage } from 'ai';
import { createOpenAI } from '@ai-sdk/openai';
import { createGoogle } from '@ai-sdk/google';
import { getMember, deny } from '@/lib/integrations/auth';
import { getIntegration } from '@/lib/integrations/secrets';
import { providerDown } from '@/lib/ai/model';
import { supabaseAdmin } from '@/lib/supabase/admin';

// Sets an idea's cover from the server: either generated by the workspace's image model (OpenAI or Gemini; Claude
// does not make images) from the idea's title, hook and angle, or copied from a picture the web already has (a
// reference video's thumbnail). The file lands in idea-covers under <workspace>/<idea>/ like an uploaded cover, and
// the idea row is updated on the member's own session so RLS decides who may change it.
export const maxDuration = 120;

export const STYLES: Record<string, string> = {
  photo: 'cinematic photograph, shallow depth of field, dramatic natural light, rich color grade',
  bold: 'bold flat graphic design, chunky shapes, saturated two-tone palette, strong contrast, poster-like',
  illustration: 'editorial illustration, textured brush strokes, expressive and warm, limited palette',
  minimal: 'minimal composition, one hero object on a clean gradient backdrop, lots of negative space',
};

const MAX_BYTES = 10 * 1024 * 1024;
const EXT: Record<string, string> = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'image/gif': 'gif', 'image/avif': 'avif' };
const blockedHost = (h: string) => /^(localhost|.*\.local|.*\.internal|.*\.localhost)$/i.test(h) || /^\[?[0-9a-f:.]+\]?$/i.test(h);

type Idea = { id: string; workspace_id: string; brand_id: string; title: string; hook: string | null; audience: string | null; promise: string | null; type: string; cover_path: string | null; cover_mode: string; body: string[] };

function prompt(i: Idea, brand: { name: string; color: string | null; tone: string[] } | null, style: string, extra: string) {
  const lines = [
    'A 16:9 YouTube thumbnail background image for a video titled "' + i.title + '".',
    i.hook ? 'The headline that will be placed over it says "' + i.hook + '", so leave a calm area for text.' : 'Leave a calm area for a headline to be placed over it.',
    i.audience ? 'Audience: ' + i.audience + '.' : '',
    i.promise ? 'What the viewer gets: ' + i.promise + '.' : '',
    (i.body || []).slice(0, 2).join(' ').slice(0, 300),
    brand ? 'Brand: ' + brand.name + (brand.color ? ', accent color ' + brand.color : '') + (brand.tone.length ? ', tone ' + brand.tone.slice(0, 3).join(', ') : '') + '.' : '',
    'Style: ' + (STYLES[style] || STYLES.photo) + '.',
    extra ? 'Direction: ' + extra : '',
    'High contrast, eye-catching, instantly readable at a small size. No text, no letters, no numbers, no logos, no watermarks, no borders.',
  ];
  return lines.filter(Boolean).join('\n');
}

// The provider's own words, without the SDK's retry wrapper.
const cleanError = (err: unknown) => String((err as { message?: string })?.message || err || 'The image model failed.').replace(/^Failed after \d+ attempts?\. Last error: /i, '').replace(/^AI_[A-Za-z]+:\s*/, '').slice(0, 300);

// OpenAI first, then Gemini when OpenAI is out of credits, rejects its key or is down (the same rule as text models).
async function imageFromModel(ws: string, text: string): Promise<{ bytes: Uint8Array; type: string; model: string }> {
  const [openai, gemini] = await Promise.all([getIntegration(ws, 'openai').catch(() => null), getIntegration(ws, 'gemini').catch(() => null)]);
  if (!openai && !gemini) throw Object.assign(new Error('Connect OpenAI or Gemini in Integrations to generate covers. Claude does not make images.'), { status: 409 });
  const tries: (() => Promise<{ bytes: Uint8Array; type: string; model: string }>)[] = [];
  if (openai) tries.push(async () => {
    const r = await generateImage({ model: createOpenAI({ apiKey: openai.secret.apiKey }).image('gpt-image-1'), prompt: text, size: '1536x1024', providerOptions: { openai: { quality: 'medium' } } });
    return { bytes: r.image.uint8Array, type: r.image.mediaType || 'image/png', model: 'OpenAI gpt-image-1' };
  });
  if (gemini) tries.push(async () => {
    const r = await generateImage({ model: createGoogle({ apiKey: gemini.secret.apiKey }).image('gemini-2.5-flash-image'), prompt: text, aspectRatio: '16:9' });
    return { bytes: r.image.uint8Array, type: r.image.mediaType || 'image/png', model: 'Gemini 2.5 Flash Image' };
  });
  const failed: string[] = [];
  for (const t of tries) {
    try { return await t(); } catch (err) { failed.push(cleanError(err)); if (!providerDown(err)) break; }
  }
  throw Object.assign(new Error(failed.join(' Then: ')), { status: 502 });
}

async function imageFromUrl(raw: string): Promise<{ bytes: Uint8Array; type: string; model: string }> {
  let u: URL;
  try { u = new URL(raw); } catch { throw Object.assign(new Error('That is not a valid image link.'), { status: 400 }); }
  if ((u.protocol !== 'http:' && u.protocol !== 'https:') || blockedHost(u.hostname)) throw Object.assign(new Error('That image link cannot be used.'), { status: 400 });
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 15000);
  try {
    const res = await fetch(u.href, { headers: { 'user-agent': 'Mozilla/5.0 (compatible; FTGU-Studio/1.0)', accept: 'image/*' }, redirect: 'follow', signal: ctrl.signal });
    const type = (res.headers.get('content-type') || '').split(';')[0].trim().toLowerCase();
    if (!res.ok) throw Object.assign(new Error('The image could not be downloaded (' + res.status + ').'), { status: 502 });
    if (!EXT[type]) throw Object.assign(new Error('That link is not a JPG, PNG, WebP, GIF or AVIF image.'), { status: 415 });
    const buf = new Uint8Array(await res.arrayBuffer());
    if (buf.length > MAX_BYTES) throw Object.assign(new Error('That image is over 10 MB.'), { status: 413 });
    if (!buf.length) throw Object.assign(new Error('The image came back empty.'), { status: 502 });
    return { bytes: buf, type, model: '' };
  } finally { clearTimeout(t); }
}

export async function POST(request: Request) {
  const m = await getMember();
  if (!m) return deny('Sign in to set a cover.', 401);
  if (m.ctx.role === 'editor') return deny('Editors cannot change idea covers.');
  const body = await request.json().catch(() => ({}));
  const ideaId = typeof body?.ideaId === 'string' ? body.ideaId : '';
  const mode = body?.mode === 'url' ? 'url' : 'generate';
  if (!ideaId) return deny('Which idea?', 400);
  const ws = m.ctx.workspace_id;
  const { data: idea } = await m.supabase.from('ideas').select('id, workspace_id, brand_id, title, hook, audience, promise, type, cover_path, cover_mode, body').eq('id', ideaId).eq('workspace_id', ws).maybeSingle();
  if (!idea) return deny('That idea is not available.', 404);
  const i = idea as Idea;

  let img: { bytes: Uint8Array; type: string; model: string };
  try {
    if (mode === 'url') img = await imageFromUrl(String(body.url || ''));
    else {
      const { data: brand } = await m.supabase.from('brand_kits').select('name, color, tone').eq('id', i.brand_id).maybeSingle();
      img = await imageFromModel(ws, prompt(i, brand as { name: string; color: string | null; tone: string[] } | null, String(body.style || 'photo'), String(body.prompt || '').slice(0, 400)));
    }
  } catch (err) {
    const e = err as { message?: string; status?: number };
    return deny(e.message || 'The cover could not be made.', e.status || 502);
  }

  const admin = supabaseAdmin();
  const path = ws + '/' + i.id + '/cover-' + (mode === 'url' ? 'ref' : 'ai') + '-' + Date.now() + '.' + (EXT[img.type] || 'png');
  const up = await admin.storage.from('idea-covers').upload(path, img.bytes, { upsert: false, contentType: img.type });
  if (up.error) return deny('The cover could not be stored: ' + up.error.message, 502);

  const mode2 = i.cover_mode === 'hook' ? 'both' : i.cover_mode;
  const upd = await m.supabase.from('ideas').update({ cover_path: path, cover_mode: mode2, cover_focal_x: 50, cover_focal_y: 50 }).eq('id', i.id).select('id');
  if (upd.error || !upd.data || !upd.data.length) {
    await admin.storage.from('idea-covers').remove([path]);
    return deny(upd.error ? upd.error.message : 'You cannot change this idea.');
  }
  if (i.cover_path && i.cover_path !== path) await admin.storage.from('idea-covers').remove([i.cover_path]).catch(() => {});
  const logged = await m.supabase.rpc('log_activity', { p_category: 'idea', p_action: mode === 'url' ? 'set the cover from a reference' : 'generated a cover with ' + img.model, p_target_label: i.title, p_project: null, p_idea: i.id, p_event: null, p_quote: null, p_external: false });
  if (logged.error) console.warn('log_activity', logged.error.message);
  const signed = await admin.storage.from('idea-covers').createSignedUrl(path, 3600);
  return NextResponse.json({ path, url: signed.data?.signedUrl || '', coverMode: mode2, model: img.model });
}
